      if (['register','receiptUpload'].includes(type)) { const coverage=data.paymentCoverage;const first=await readReceipt(form,0);const second=type==='register'&&coverage==='individual'?await readReceipt(form,1):null;delete data.receiptFile0;delete data.receiptFile1;delete data.confirmPaid0;delete data.confirmPaid1;const uploads=[];if(first)uploads.push({side:coverage==='pair'||coverage==='both'?'both':type==='receiptUpload'?Number(coverage):0,upload:first,confirmPaid:form.querySelector('[name=confirmPaid0]')?.checked===true});if(second)uploads.push({side:1,upload:second,confirmPaid:form.querySelector('[name=confirmPaid1]')?.checked===true});if(uploads.length)data.receiptUploads=uploads;else if(type==='register'&&(form.querySelector('[name=confirmPaid0]')?.checked||form.querySelector('[name=confirmPaid1]')?.checked))throw new Error('Attach proof before confirming a payment.');else if(type==='receiptUpload')throw new Error('Choose a receipt image.'); }
